# Browserprüfung für polnische Referenznetz und die manuelle Streckenerfassung.
"""Real renderer: Polish-only reference, lazy detail tiles, toggles and preserved selection."""
import argparse
from browser_realtime import check_pages
from check_manual_route_ui import ASSETS as BASE
from check_work_report_layout import STATIC
ASSETS=['map-gestures.js','poland-rail.js',*BASE,'gps.js']
def fixture():
    css='\n'.join((STATIC/n).read_text() for n in ['tf-portal.css','work-report.css','responsive.css','portal-theme.css'])
    setup=r'''let language='de';window.I18n={t:s=>s,get language(){return language;},set(value){language=value;document.documentElement.lang=value;dispatchEvent(new Event('languagechange'));}};Object.defineProperty(navigator,'onLine',{get:()=>false});window.AndroidPortal={gps:async()=>({running:false,points:[]})};window.fetch=async()=>new Response(JSON.stringify({owner_id:1,items:[],next_offset:null}));'''
    checks=r'''
(async()=>{
 const assert=(v,m)=>{if(!v)throw Error(m);},wait=ms=>new Promise(r=>setTimeout(r,ms)),until=async fn=>{const end=performance.now()+20000;while(!fn()){if(performance.now()>end)throw Error('Timed out');await wait(25);}};
 window.GpsRecorder.localRecords=async()=>[];await startRouteKnowledge({id:1});const editor=ManualRouteEditor.mount({id:1},document.getElementById('manual'),async()=>{});await until(()=>!document.querySelector('[data-route-start]').disabled);editor.select(M1Map.points().byCode.get('AFW')[0],true);editor.select(M1Map.points().byCode.get('AFR')[0]);await wait(80);const selection=editor.waypoints.join(',');
 assert(!document.querySelector('[data-poland-rail-network]')&&!document.querySelector('script[src*=poland-rail-data]'),'German language neither draws nor loads Poland');assert(document.querySelector('[data-poland-rail-home]').hidden,'Poland navigation hidden in German');
 let maxGap=0,lastTick=performance.now();const heartbeat=setInterval(()=>{const now=performance.now();maxGap=Math.max(maxGap,now-lastTick);lastTick=now;},25);I18n.set('pl');document.querySelector('[data-poland-rail-home]').click();await until(()=>document.querySelector('#routeKnowledgeWorkspace [data-poland-rail-network]'));assert(!document.querySelector('[data-poland-rail-home]').hidden,'Polish language exposes country navigation');assert(document.querySelector('#routeKnowledgeWorkspace [data-offline-place="756135"]'),'Warszawa is in the offline background');assert(document.querySelector('[data-poland-rail-credit]'),'OSM attribution visible');assert(editor.waypoints.join(',')===selection,'Switching language retains selected German M1 points');
 const paths=document.querySelector('#routeKnowledgeWorkspace [data-poland-rail-network]').getAttribute('d');assert(paths.length>1000,'Country overview contains a real network');const plus=[...document.querySelectorAll('#routeKnowledgeWorkspace .gps-map-tools button')].find(b=>b.textContent==='+');for(let i=0;i<4;i++)plus.click();await until(()=>performance.getEntriesByType('resource').some(r=>r.name.includes('/poland-rail-data/tile-')));await wait(250);assert(document.querySelector('#routeKnowledgeWorkspace [data-poland-rail-network]'),'Detail mode retains network');assert(performance.getEntriesByType('resource').filter(r=>r.name.includes('/poland-rail-data/tile-')).length<=9,'Only visible detail tiles are loaded');
 const points=[{t:1795165200000,lat:52.23,lon:21.01,accuracy:5,speed:0},{t:1795165210000,lat:52.231,lon:21.011,accuracy:5,speed:5}],original=JSON.stringify(points),rec=GpsRecorder.mount({userId:1,journeyId:'poland-demo-test',container:document.getElementById('gps'),demo:true,readonly:()=>true,trainNumber:()=>''});await rec.readyPromise;rec.record={ended:true,points,manual_stops:[],stop_edits:{}};rec.m1Data=RailNetworkSeed;rec.mapState={mode:'free',zoom:12,center:M1Map.project({lat:52.23,lon:21.01})};rec.setExpanded(true);await until(()=>document.querySelector('#gps [data-poland-rail-network]'));assert(JSON.stringify(points)===original,'Reference never alters GPS points');
 for(const lang of ['en','de']){I18n.set(lang);await wait(100);assert(!document.querySelector('[data-poland-rail-network]')&&!document.querySelector('[data-poland-rail-credit]'),'All Polish map layers/credits removed for '+lang);assert(document.querySelector('[data-poland-rail-home]').hidden,'Poland navigation removed');assert(editor.waypoints.join(',')===selection,'Selected M1 route remains intact');}
 I18n.set('pl');await until(()=>document.querySelector('#gps [data-poland-rail-network]'));rec.mapRail.click();assert(!document.querySelector('#gps [data-poland-rail-network]'),'Railway map button hides Poland too');assert(!document.querySelector('image[href*="tile.openstreetmap"]'),'No external map tiles');clearInterval(heartbeat);assert(maxGap<1500,'Polish tiles do not block the UI for multiple seconds: '+Math.round(maxGap)+'ms');parent.postMessage({layoutStatus:'pass',message:'max UI gap '+Math.round(maxGap)+'ms'},'*');
})().catch(e=>parent.postMessage({layoutStatus:'fail',message:e.stack},'*'));
'''
    html='<div id="routeKnowledgeWorkspace"></div><div id="manual"></div><div id="gps"></div>'
    return '<!doctype html><html lang="de"><head><meta charset="utf-8"><style>'+css+'</style></head><body>'+html+'<script>'+setup+'</script>'+''.join('<script src="/tf/'+n+'"></script>' for n in ASSETS)+'<script>'+checks+'</script></body></html>'
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--output-dir',required=True);a=p.parse_args();assets={'/tf/'+n:STATIC/n for n in ASSETS};assets.update({'/tf/poland-rail-data/'+p.name:p for p in (STATIC/'poland-rail-data').glob('*.js')});check_pages(fixture,a.output_dir,widths=(800,375),assets=assets,label='Polish-only offline rail network',cpu_rate=4,timeout=60)
